  currency_raw TEXT,                     -- 'UZS' | 'USD' | …
  condition TEXT,                        -- 'new' | 'used'
  city TEXT,
  posted_at TIMESTAMPTZ,                 -- when the listing was posted (if known)
  observed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  raw_text TEXT,
